-- Icecrown: the Valley of Lost Hope dailies (13373, 13374, 13376, 13380 to 13382, 13404, 13406) need Gargoyle
-- Ambushers, Frostbrood Sentries, Scourge War Machines and Bombardment Infantry and Captains, which were not spawned.
-- Positions from 5.4.8. The Infantry and Captain templates here had the 3.3.5 placeholder level 1 and friendly faction,
-- the 5.4.8 template is level 80 and hostile. The Gargoyle Ambusher and Frostbrood Sentry fly in 5.4.8.
DELETE FROM `creature` WHERE `guid` BETWEEN 8320200 AND 8320271;
UPDATE `creature_template` SET `minlevel` = 80, `maxlevel` = 80, `exp` = 2, `faction_A` = 14, `faction_H` = 14, `flags_extra` = 64 WHERE `entry` IN (32399, 32410);
UPDATE `creature_template` SET `InhabitType` = 7 WHERE `entry` IN (32188, 31721);

-- The Frostbrood Destroyers of The Last Line Of Defense (13086) stand in phase 175, which the Valley of Echoes aura
-- (57569, quests 13070 to 13086) gives. Sergeant Kregga (13258, 13262) is phase 172 (aura 59087, Horde) and Father
-- Kamaros (13481, 13482) phase 175 (aura 58139, after quest 13144).
DELETE FROM `creature` WHERE `guid` BETWEEN 8320272 AND 8320276;
UPDATE `creature_template` SET `exp` = 2 WHERE `entry` = 30575;

DELETE FROM `spell_area` WHERE (`spell` = 59087 AND `area` = 4522 AND `quest_start` = 13258) OR (`spell` = 58139 AND `area` = 4531 AND `quest_start` = 13144);

-- A phase aura replaces the default phase for the player, so every unphased spawn of an area that gives one vanishes
-- unless the area also gives the default phase 169. This covers the areas that already had a phase aura here and the
-- two added above.
DELETE FROM `phase_area` WHERE `PhaseId` = 169 AND `AreaId` IN (4477, 4501, 4504, 4505, 4506, 4519, 4522, 4531, 4580, 4593);
